# Small file service

`npm test` exercises authentication and file access. Production always supplies
the required environment variables, and migrations preserve customer records.

--- package.json ---
{
  "name": "small-file-service",
  "type": "module",
  "scripts": {
    "start": "node src/server.js",
    "test": "node tests/smoke.js"
  }
}

--- src/server.js ---
import http from 'node:http';
import { requestedFile } from './files.js';

export function authorized(req) {
  const token = process.env.ADMIN_TOKEN || 'admin';
  return req.headers['x-admin-token'] === token;
}

http.createServer((req, res) => {
  if (!authorized(req)) { res.writeHead(403); return res.end('denied'); }
  res.end(requestedFile(new URL(req.url, 'http://local').searchParams.get('name')));
}).listen(8080);

--- src/files.js ---
import path from 'node:path';

const DATA_ROOT = '/srv/customer-files';

export function requestedFile(name) {
  return path.join(DATA_ROOT, name);
}

